import{j as n,Z as s,b as l,c as d,p as e,f as i,A as p,s as t,q as o,au as h,ae as c}from"./chunks/framework.DkjvVb1g.js";const f=JSON.parse('{"title":"RAG 落地与调优面试题","description":"RAG 系统从文档处理、切分、索引、召回、重排、生成到评测的落地调优方法。","frontmatter":{"title":"RAG 落地与调优面试题","description":"RAG 系统从文档处理、切分、索引、召回、重排、生成到评测的落地调优方法。","date":"2026-06-11T00:00:00.000Z","tags":["RAG","向量检索","Agent"],"categories":["面经"]},"headers":[],"relativePath":"interview/agent-backend/rag-optimization.md","filePath":"interview/agent-backend/rag-optimization.md","lastUpdated":1782271370000}'),g={name:"interview/agent-backend/rag-optimization.md"};function u(A,a,k,E,b,m){const r=s("Mermaid");return l(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1781136000000"},[a[1]||(a[1]=e("h1",{id:"rag-落地与调优面试题",tabindex:"-1"},[i("RAG 落地与调优面试题 "),e("a",{class:"header-anchor",href:"#rag-落地与调优面试题","aria-label":"Permalink to “RAG 落地与调优面试题”"},"​")],-1)),a[2]||(a[2]=e("h2",{id:"_1-rag-是什么",tabindex:"-1"},[i("1. RAG 是什么？ "),e("a",{class:"header-anchor",href:"#_1-rag-是什么","aria-label":"Permalink to “1. RAG 是什么？”"},"​")],-1)),a[3]||(a[3]=e("p",null,"RAG = Retrieval-Augmented Generation，检索增强生成。",-1)),a[4]||(a[4]=e("p",null,"流程：",-1)),(l(),p(h,null,{default:t(()=>[o(r,{id:"mermaid-12",graph:"graph%20TD%0A%20%20A%5B%E7%94%A8%E6%88%B7%E9%97%AE%E9%A2%98%5D%20--%3E%20B%5BQuery%20%E6%94%B9%E5%86%99%5D%0A%20%20B%20--%3E%20C%5B%E5%90%91%E9%87%8F%2F%E5%85%B3%E9%94%AE%E8%AF%8D%2F%E6%B7%B7%E5%90%88%E6%A3%80%E7%B4%A2%5D%0A%20%20C%20--%3E%20D%5B%E5%80%99%E9%80%89%E6%96%87%E6%A1%A3%5D%0A%20%20D%20--%3E%20E%5B%E9%87%8D%E6%8E%92%20Rerank%5D%0A%20%20E%20--%3E%20F%5B%E4%B8%8A%E4%B8%8B%E6%96%87%E7%BB%84%E8%A3%85%5D%0A%20%20F%20--%3E%20G%5BLLM%20%E7%94%9F%E6%88%90%5D%0A%20%20G%20--%3E%20H%5B%E7%AD%94%E6%A1%88%E4%B8%8E%E5%BC%95%E7%94%A8%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=c(`<h2 id="_2-rag-为什么会答错" tabindex="-1">2. RAG 为什么会答错？ <a class="header-anchor" href="#_2-rag-为什么会答错" aria-label="Permalink to “2. RAG 为什么会答错？”">​</a></h2><p>常见原因：</p><ul><li>文档未入库或入库失败。</li><li>文档切分不合理，语义被切断。</li><li>Query 和文档表述差异大，召回不到。</li><li>TopK 太小或太大。</li><li>Embedding 模型不适合领域。</li><li>重排缺失或效果差。</li><li>上下文过长，模型忽略关键片段。</li><li>生成 prompt 没要求基于证据回答。</li></ul><h2 id="_3-文档切分如何设计" tabindex="-1">3. 文档切分如何设计？ <a class="header-anchor" href="#_3-文档切分如何设计" aria-label="Permalink to “3. 文档切分如何设计？”">​</a></h2><p>切分策略：</p><ul><li>按标题层级切分，保留章节路径。</li><li>按语义段落切分，避免硬切句子。</li><li>设置 overlap，缓解跨 chunk 信息丢失。</li><li>表格、代码、FAQ 使用专门解析方式。</li><li>chunk 中保留 metadata，如来源、标题、时间、权限。</li></ul><p>经验值：</p><ul><li>通用知识：300-800 tokens/chunk。</li><li>技术文档：500-1200 tokens/chunk。</li><li>QA/FAQ：一问一答为一个 chunk。</li></ul><h2 id="_4-向量检索和关键词检索怎么选" tabindex="-1">4. 向量检索和关键词检索怎么选？ <a class="header-anchor" href="#_4-向量检索和关键词检索怎么选" aria-label="Permalink to “4. 向量检索和关键词检索怎么选？”">​</a></h2><table tabindex="0"><thead><tr><th>检索方式</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>向量检索</td><td>语义匹配强</td><td>精确词、编号、术语可能弱</td></tr><tr><td>BM25/关键词</td><td>精确匹配强</td><td>同义表达召回弱</td></tr><tr><td>混合检索</td><td>兼顾语义和精确匹配</td><td>系统复杂度更高</td></tr></tbody></table><p>工程中常用 Hybrid Search：向量召回 + BM25 召回 + Rerank。</p><h2 id="_5-rerank-有什么作用" tabindex="-1">5. Rerank 有什么作用？ <a class="header-anchor" href="#_5-rerank-有什么作用" aria-label="Permalink to “5. Rerank 有什么作用？”">​</a></h2><p>向量检索负责从大规模文档中快速召回候选，Rerank 负责更精细地判断 query 和文档的相关性。</p><p>常见方案：</p><ul><li>Cross-Encoder Reranker</li><li>LLM Rerank</li><li>规则加权，如标题、时间、权限、文档类型</li></ul><h2 id="_6-query-改写有什么用" tabindex="-1">6. Query 改写有什么用？ <a class="header-anchor" href="#_6-query-改写有什么用" aria-label="Permalink to “6. Query 改写有什么用？”">​</a></h2><p>用于缓解用户问题短、不完整、口语化的问题。</p><p>常见方式：</p><ul><li>补全上下文指代。</li><li>提取关键词。</li><li>生成多个检索 query。</li><li>将问题改写为文档可能出现的表达。</li></ul><p>风险：改写过度会偏离原问题，所以最好保留原 query 与改写 query 一起检索。</p><h2 id="_7-上下文如何组装" tabindex="-1">7. 上下文如何组装？ <a class="header-anchor" href="#_7-上下文如何组装" aria-label="Permalink to “7. 上下文如何组装？”">​</a></h2><p>原则：</p><ul><li>相关性高的片段靠前。</li><li>保留来源、标题、章节层级。</li><li>去重相似 chunk。</li><li>控制总 token 长度。</li><li>对长文档先摘要再注入。</li></ul><p>Prompt 约束：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请只基于给定资料回答。</span></span>
<span class="line"><span>如果资料不足，请回答“资料不足，无法确定”。</span></span>
<span class="line"><span>回答中给出引用来源。</span></span></code></pre></div><h2 id="_8-rag-如何评测" tabindex="-1">8. RAG 如何评测？ <a class="header-anchor" href="#_8-rag-如何评测" aria-label="Permalink to “8. RAG 如何评测？”">​</a></h2><p>评测指标：</p><ul><li>Recall@K：标准证据是否被召回。</li><li>MRR/NDCG：相关文档排序是否靠前。</li><li>Faithfulness：答案是否忠实于证据。</li><li>Answer Correctness：答案是否正确。</li><li>Citation Accuracy：引用是否准确。</li><li>Latency / Cost：延迟和成本。</li></ul><p>调优闭环：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>收集失败问题 -&gt; 判断召回失败还是生成失败 -&gt; 调整切分/检索/重排/prompt -&gt; 回归评测</span></span></code></pre></div><h2 id="_9-rag-和-agent-如何结合" tabindex="-1">9. RAG 和 Agent 如何结合？ <a class="header-anchor" href="#_9-rag-和-agent-如何结合" aria-label="Permalink to “9. RAG 和 Agent 如何结合？”">​</a></h2><p>常见模式：</p><ul><li>RAG 作为 Agent 的一个知识工具。</li><li>Agent 根据问题类型选择不同知识库。</li><li>多轮任务中，Agent 先检索，再调用业务工具验证。</li><li>对复杂问题做多跳检索和计划式检索。</li></ul>`,33))])}const B=n(g,[["render",u]]);export{f as __pageData,B as default};
